import codecs
original = codecs.lookup_error('strict')
name = 'custom\ud800'
seen = []
def repair(error):
    seen.append(error.object is name)
    return (b'8', error.end)
codecs.register_error('strict', repair)
sentinel = ValueError('failure')
def fail(*args):
    raise sentinel
def search(normalized):
    print('search', repr(normalized))
    return codecs.CodecInfo(fail, fail, name=normalized)
codecs.register(search)
for attempt in range(2):
    try:
        codecs.encode('x', name, 'strict')
    except Exception as error:
        print(type(error).__name__, ascii(str(error)), error is sentinel)
        print(getattr(error, '__notes__', None))
    codecs.register_error('strict', original)
print(seen)

